mapper.select:
select max(round_no)
from wf_multi_instance_round
where process_instance_id=#{processInstanceId} and activity_id=#{activityId}

mapper.update:
update wf_multi_instance_round
set members_json=#{membersJson}, revision_no=#{newRevision}
where round_id=#{roundId} and revision_no=#{expectedRevision}
  and round_status='ACTIVE'

update wf_multi_instance_round set round_status='TERMINATED', terminate_time=greatest(current_timestamp(3), create_time, coalesce(return_time, create_time)) where round_status in ('ACTIVE', 'RETURNED') and
round_id in #{roundId}
1=0

mapper.select:
select count(*) from wf_multi_instance_round where round_status in ('ACTIVE', 'RETURNED') and
process_instance_id in #{instanceId}
1=0

select count(*) from wf_multi_instance_round where
process_instance_id in #{instanceId}
1=0

mapper.delete:
delete from wf_multi_instance_round where
process_instance_id in #{instanceId}
1=0
